enum class FocusResult:u32 { Focused,Missing,PrepareFailed,Starting,NoWindow,Exited,Faulted };
static FocusResult FocusApp(u32 kind){
 auto*a=MultiAppRuntime::AppForKind(kind);if(!a){BackendDiagnostics::Record(BackendDiagnostics::Kind::AppClick,0,kind,10);return FocusResult::Missing;}auto*p=a->loaded.process;if(!p){BackendDiagnostics::Record(BackendDiagnostics::Kind::AppClick,0,kind,15);return FocusResult::PrepareFailed;}p->launchAttempts++;BackendDiagnostics::Record(BackendDiagnostics::Kind::AppClick,p->id,kind,(u64)p->state);BackendDiagnostics::Record(BackendDiagnostics::Kind::LaunchState,p->id,(u64)p->state,(u64)a->stage,a->ready?1:0,MultiAppRuntime::state.scheduler.currentId);
 if(p->state==Process::State::Exited)return FocusResult::Exited;if(p->state==Process::State::Faulted)return FocusResult::Faulted;
 if(!a->ready){BackendDiagnostics::Record(BackendDiagnostics::Kind::Error,p->id,kind,(u64)a->stage,a->error);return FocusResult::PrepareFailed;}
 if(DxeServices::RaiseFirstWindowForOwner(p->id))return FocusResult::Focused;
 if(p->state==Process::State::Created||p->state==Process::State::Ready){BackendDiagnostics::Record(BackendDiagnostics::Kind::LaunchState,p->id,kind,0x454E5155);if(!BootAppRunner::LaunchKind(MultiAppRuntime::state,PlatformBootstrap::state,kind))return p->state==Process::State::Faulted?FocusResult::Faulted:FocusResult::Starting;if(DxeServices::RaiseFirstWindowForOwner(p->id))return FocusResult::Focused;return FocusResult::NoWindow;}return FocusResult::NoWindow;
}
